/**
 * Subtle square flicker for the .bg_finish SVG grid.
 *
 * Each <rect> mostly sits at its resting opacity. At random intervals a few
 * squares (never more than CONFIG.maxConcurrent at once) fade down to a bit
 * under their own opacity — occasionally to roughly half — then fade back.
 *
 * Drop into Slater. Self-contained, no CSS needed.
 *
 * DEBUGGING: leave CONFIG.debug = true for now. It logs how many squares it
 * found and runs an obvious, loud version of the effect so you can confirm
 * it's wired up. Once you see it moving, set debug = false for the real,
 * subtle settings.
 */
(function () {
  'use strict';

  const CONFIG = {
    // Which SVG(s) to animate. Every <rect> inside a match gets picked up.
    svgSelector: '.bg_finish',

    // Set true to log counts + run a loud, obvious version for debugging.
    debug: false,

    // Max squares mid-flicker at once. Higher = more squares moving together.
    maxConcurrent: 16,

    // Random gap between flicker attempts, in ms. Lower = busier.
    spawnInterval: [80, 140],

    // Normal dip: fade down to this fraction of the square's OWN opacity.
    // Depth (not speed) drives visibility — shallow + slow reads as nothing.
    mildDip: [0.45, 0.65],

    // Occasional deeper pulse, plus how often it fires (0–1).
    deepDip: [0.25, 0.4],
    deepChance: 0.22,

    // Timing of one flicker, in ms. Slow + languid.
    downDuration: [600, 1400],
    hold: [0, 300],
    upDuration: [600, 1400],

    easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
  };

  // Loud overrides applied only while debugging, so the effect is unmissable.
  const DEBUG_OVERRIDES = {
    maxConcurrent: 14,
    spawnInterval: [40, 120],
    mildDip: [0.2, 0.4],
    deepDip: [0.05, 0.15],
    deepChance: 0.4,
    downDuration: [150, 350],
    hold: [0, 120],
    upDuration: [200, 500],
  };

  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const rand = (min, max) => min + Math.random() * (max - min);

  function initSquareFlicker() {
    if (reduceMotion) {
      if (CONFIG.debug) console.log('[square-flicker] skipped: prefers-reduced-motion is on');
      return;
    }

    if (CONFIG.debug) Object.assign(CONFIG, DEBUG_OVERRIDES);

    const svgs = document.querySelectorAll(CONFIG.svgSelector);

    const rects = [];
    const base = new WeakMap();

    svgs.forEach((svg) => {
      svg.querySelectorAll('rect').forEach((rect) => {
        const o = parseFloat(getComputedStyle(rect).fillOpacity) || 1;
        base.set(rect, o);
        rects.push(rect);
      });
    });

    if (CONFIG.debug) {
      console.log(
        `[square-flicker] matched ${svgs.length} element(s) for "${CONFIG.svgSelector}", found ${rects.length} <rect>(s)`
      );
    }

    if (!rects.length) {
      if (CONFIG.debug) console.warn(
        '[square-flicker] no rects — check that the SVG is inline and the selector is right');
      return;
    }

    const active = new Set();

    function flicker(rect) {
      const start = base.get(rect);
      const deep = Math.random() < CONFIG.deepChance;
      const mult = deep ?
        rand(CONFIG.deepDip[0], CONFIG.deepDip[1]) :
        rand(CONFIG.mildDip[0], CONFIG.mildDip[1]);

      const target = start * mult;
      const down = rand(CONFIG.downDuration[0], CONFIG.downDuration[1]);
      const up = rand(CONFIG.upDuration[0], CONFIG.upDuration[1]);
      const hold = rand(CONFIG.hold[0], CONFIG.hold[1]);

      active.add(rect);

      rect.style.transition = `fill-opacity ${down}ms ${CONFIG.easing}`;
      rect.style.fillOpacity = String(target);

      setTimeout(() => {
        rect.style.transition = `fill-opacity ${up}ms ${CONFIG.easing}`;
        rect.style.fillOpacity = String(start);
        setTimeout(() => active.delete(rect), up);
      }, down + hold);
    }

    function tick() {
      if (!document.hidden && active.size < CONFIG.maxConcurrent) {
        let pick;
        for (let i = 0; i < 6; i++) {
          const candidate = rects[(Math.random() * rects.length) | 0];
          if (!active.has(candidate)) { pick = candidate; break; }
        }
        if (pick) flicker(pick);
      }
      setTimeout(tick, rand(CONFIG.spawnInterval[0], CONFIG.spawnInterval[1]));
    }

    tick();
  }

  initSquareFlicker();
})();


